        let bInputs = Inputs.vectors(H.Vector.self, seed: 0x90D9_B439_DD04_B29B)
        let cInputs = Inputs.vectors(H.Vector.self, seed: 0x90D9_B539_DD04_B44E)
        let dInputs = Inputs.vectors(H.Vector.self, seed: 0x90D9_B639_DD04_B601)
        for (a, b, c, d) in mixedQuadruples(
            aInputs,
            bInputs,
            cInputs,
            dInputs,
            seed: 0x4BFB_DBCC_C968_15E4
        ) {
            let (_, portLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                unsafe H.appendInterleaved4(a, b, c, d, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                H.appendInterleaved4(a, b, c, d, to: &output)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c)), d: \(describe(d))"
            )
        }
        mismatches.record()
    }
}
